import { spawn } from 'node:child_process';
import net from 'node:net';
import { setTimeout as delay } from 'node:timers/promises';

const port = 55881;
const proc = spawn('/Users/ag/.asdf/installs/nodejs/24.12.0/bin/wrangler', [
  'dev', ...(process.env.CONTROL_SCRIPT ? [process.env.CONTROL_SCRIPT] : []), '--config', '/private/tmp/edgezero-overflow-all-20261021-b/overflow-cloudflare/wrangler.toml',
  '--port', String(port), '--ip', '127.0.0.1', '--local', '--persist-to', '/private/tmp/edgezero-overflow-cf-control-state'
], { env: { ...process.env, WRANGLER_SEND_METRICS: 'false', WRANGLER_LOG_PATH: '/private/tmp/edgezero-pr275-wrangler-logs' }});
let logs = '';
for (const stream of [proc.stdout, proc.stderr]) stream.on('data', bytes => {
  if (logs.length < 65536) logs += bytes.toString();
});
async function request(label, length) {
  const payload = length === null ? '' : `${length.toString(16)}\r\n${'x'.repeat(length)}\r\n0\r\n\r\n`;
  const wire = `POST /progress/overflow/inbound HTTP/1.1\r\nHost: 127.0.0.1:${port}\r\nx-request-token: ${label}\r\nConnection: close\r\n${length === null ? 'Content-Length: 0' : 'Transfer-Encoding: chunked'}\r\n\r\n${payload}`;
  const result = await new Promise((resolve, reject) => {
    const socket = net.connect({ host: '127.0.0.1', port });
    let reply = '';
    socket.setTimeout(6000, () => socket.destroy(new Error('diagnostic timeout')));
    socket.on('connect', () => socket.write(wire));
    socket.on('data', bytes => {
      reply += bytes.toString();
      if (reply.length > 8192) socket.destroy(new Error('diagnostic capture bound'));
      const boundary = reply.indexOf('\r\n\r\n');
      if (boundary < 0) return;
      const head = reply.slice(0, boundary);
      const body = reply.slice(boundary + 4);
      const length = /content-length: (\d+)/i.exec(head);
      if ((length && Buffer.byteLength(body) >= Number(length[1])) || (!length && body.endsWith('\r\n0\r\n\r\n'))) {
        resolve(reply);
        socket.destroy();
      }
    });
    socket.on('error', reject);
    socket.on('end', () => resolve(reply));
  });
  console.log(JSON.stringify({ label, length, reply: result }));
}
try {
  for (let index = 0; index < 150 && !logs.includes('Ready on'); index++) {
    if (proc.exitCode !== null) throw new Error('runtime exited');
    await delay(100);
  }
  if (!logs.includes('Ready on')) throw new Error('runtime startup timeout');
  for (const [label, length] of [
    ['baseline', 1024], ['overflow-a', 1025], ['after-a', null], ['recover-a', null],
    ['overflow-b', 1025], ['after-b', 1], ['recover-b', 1],
    ['overflow-c', 1025], ['after-c', 1024], ['recover-c', 1024]
  ]) await request(label, length);
} finally {
  proc.kill('SIGTERM');
  await Promise.race([new Promise(resolve => proc.once('exit', resolve)), delay(5000)]);
  if (proc.exitCode === null && proc.signalCode === null) proc.kill('SIGKILL');
  console.log(JSON.stringify({ event: 'runtime-log', logs }));
}

export default {
  async fetch(request) {
    const token = request.headers.get('x-request-token');
    console.log(JSON.stringify({ event: 'control-entry', token }));
    let size = 0;
    if (request.body) {
      const reader = request.body.getReader();
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        size += value.byteLength;
        if (size > 1024) {
          reader.cancel().catch(() => {});
          console.log(JSON.stringify({ event: 'control-return', token, status: 413 }));
          return new Response(JSON.stringify({ error: { kind: 'payload_too_large', message: 'request body too large', status: 413 } }), { status: 413 });
        }
      }
      reader.releaseLock();
    }
    console.log(JSON.stringify({ event: 'control-return', token, status: 200 }));
    return Response.json({ case: 'inbound', received: size, qualification: false });
  }
};

